content.text:
Brief:
Un labyrinthe de haies vu du dessus, joué au tour par tour. Le joueur guide un hérisson case par case en glissant le doigt vers une direction. Chaque déplacement coûte un pas, et des pommes posées dans les allées rapportent des points. La partie est gagnée quand le hérisson atteint la sortie, et elle est bloquée si plus aucun pas ne reste. Aucun chronomètre ne presse le joueur.

Plan:
{"gameType":"puzzle-board","input":"swipe-lanes","lang":"fr","loop":"Glissez le doigt pour guider le hérisson case par case dans les haies, ramassez des pommes pour marquer des points et atteignez la sortie avant d'épuiser vos pas.","slug":"le-labyrinthe-du-herisson","style":"paper-cut","title":"Le Labyrinthe du Hérisson"}

Game source (line-numbered):
1| 
2| <!doctype html>
3| <html lang="fr">
4| <head>
5| <meta charset="utf-8">
6| <meta name="viewport" content="width=device-width, initial-scale=1">
7| <title>Le Labyrinthe du Hérisson</title>
8| <style>
9|   html, body {
10|     margin: 0; padding: 0; width: 100%; height: 100%;
11|     background: #f4ecd8;
12|     overflow: hidden;
13|     touch-action: none;
14|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
15|   }
16|   #game {
17|     display: block;
18|     width: 100vw;
19|     height: 100dvh;
20|     touch-action: none;
21|   }
22| </style>
23| </head>
24| <body>
25| <canvas id="game"></canvas>
26| <script>
27| // ---- Bridge helper (verbatim) ----
28| const CARTRIDGE = {
29|   send(type, payload = {}) {
30|     window.parent.postMessage(
31|       { source: "cartridge", v: 1, type, payload },
32|       "*",
33|     );
34|   },
35| };
36| 
37| window.addEventListener("message", (event) => {
38|   const data = event.data;
39|   if (!data || data.source !== "cartridge-host") return;
40|   if (data.type === "pause") paused = true;
41|   if (data.type === "resume") paused = false;
42|   if (data.type === "reset") backToTitle();
43| });
44| 
45| // ---- Game setup ----
46| const canvas = document.getElementById("game");
47| const ctx = canvas.getContext("2d");
48| 
49| let paused = false;
50| let dpr = Math.max(1, window.devicePixelRatio || 1);
51| 
52| function resize() {
53|   dpr = Math.max(1, window.devicePixelRatio || 1);
54|   const w = window.innerWidth;
55|   const h = window.innerHeight;
56|   canvas.width = Math.floor(w * dpr);
57|   canvas.height = Math.floor(h * dpr);
58|   canvas.style.width = w + "px";
59|   canvas.style.height = h + "px";
60|   draw();
61| }
62| window.addEventListener("resize", resize);
63| 
64| // ---- Palette ----
65| const COL_BG = "#f4ecd8";
66| const COL_LAYER = "#e07a5f";
67| const COL_ACCENT = "#3d405b";
68| const COL_HILITE = "#81b29a";
69| 
70| // ---- Seeded jitter ----
71| function makeRng(seed) {
72|   let s = seed >>> 0;
73|   return function () {
74|     s = (s * 1664525 + 1013904223) >>> 0;
75|     return (s & 0xffffffff) / 4294967296;
76|   };
77| }
78| const jitterRng = makeRng(1337);
79| function jitterVal() {
80|   return (jitterRng() - 0.5) * 3;
81| }
82| 
83| // ---- Board / maze ----
84| const LANES = 4; // columns = lanes for swipe control
85| const ROWS = 7;
86| const GRID_W = LANES;
87| const GRID_H = ROWS;
88| 
89| let grid = []; // grid[row][col] = { wallsRight, wallsBottom, apple, visited }
90| let hedgehogRow, hedgehogCol;
91| let exitRow, exitCol;
92| let lane = 0; // current column lane
93| let stepsLeft = 0;
94| let score = 0;
95| let moves = 0;
96| let level = 1;
97| let state = "title"; // title, playing, ended
98| let endReason = null;
99| let message = "";
100| 
101| // jitter cache per cell-edge for stable irregular look
102| let jitterCache = {};
103| function getJitter(key) {
104|   if (!(key in jitterCache)) {
105|     jitterCache[key] = { dx: jitterVal(), dy: jitterVal() };
106|   }
107|   return jitterCache[key];
108| }
109| 
110| function genMaze(seed) {
111|   const rng = makeRng(seed);
112|   const cells = [];
113|   for (let r = 0; r < GRID_H; r++) {
114|     const row = [];
115|     for (let c = 0; c < GRID_W; c++) {
116|       row.push({ right: true, bottom: true, visited: false, apple: false });
117|     }
118|     cells.push(row);
119|   }
120|   // randomized DFS to carve maze, walls = true means wall present
121|   const stack = [[0, 0]];
122|   cells[0][0].visited = true;
123|   function neighbors(r, c) {
124|     const list = [];
125|     if (r > 0 && !cells[r - 1][c].visited) list.push([r - 1, c, "up"]);
126|     if (r < GRID_H - 1 && !cells[r + 1][c].visited) list.push([r + 1, c, "down"]);
127|     if (c > 0 && !cells[r][c - 1].visited) list.push([r, c - 1, "left"]);
128|     if (c < GRID_W - 1 && !cells[r][c + 1].visited) list.push([r, c + 1, "right"]);
129|     return list;
130|   }
131|   while (stack.length) {
132|     const [r, c] = stack[stack.length - 1];
133|     const opts = neighbors(r, c);
134|     if (opts.length === 0) {
135|       stack.pop();
136|       continue;
137|     }
138|     const pick = opts[Math.floor(rng() * opts.length)];
139|     const [nr, nc, dir] = pick;
140|     if (dir === "up") cells[r - 1][nc ? c : c].bottom = false, cells[nr][nc].bottom = false;
141|     if (dir === "down") cells[r][c].bottom = false;
142|     if (dir === "left") cells[r][c - 1 === nc ? nc : nc].right = false, cells[nr][nc].right = false;
143|     if (dir === "right") cells[r][c].right = false;
144|     cells[nr][nc].visited = true;
145|     stack.push([nr, nc]);
146|   }
147|   // place apples on random open cells (not start, not exit)
148|   const appleCount = 4 + Math.floor(rng() * 2);
149|   let placed = 0;
150|   let attempts = 0;
151|   while (placed < appleCount && attempts < 200) {
152|     attempts++;
153|     const r = Math.floor(rng() * GRID_H);
154|     const c = Math.floor(rng() * GRID_W);
155|     if (r === 0 && c === 0) continue;
156|     if (r === GRID_H - 1 && c === GRID_W - 1) continue;
157|     if (cells[r][c].apple) continue;
158|     cells[r][c].apple = true;
159|     placed++;
160|   }
161|   return cells;
162| }
163| 
164| function setupLevel(idx) {
165|   grid = genMaze(idx * 977 + 42);
166|   hedgehogRow = 0;
167|   hedgehogCol = 0;
168|   lane = 0;
169|   exitRow = GRID_H - 1;
170|   exitCol = GRID_W - 1;
171|   stepsLeft = GRID_W * GRID_H + 6;
172|   jitterCache = {};
173|   message = "";
174| }
175| 
176| function totalApples() {
177|   let n = 0;
178|   for (let r = 0; r < GRID_H; r++)
179|     for (let c = 0; c < GRID_W; c++) if (grid[r][c].apple) n++;
180|   return n;
181| }
182| 
183| function canMove(r, c, dir) {
184|   if (dir === "left") {
185|     if (c === 0) return false;
186|     return !grid[r][c - 1].right;
187|   }
188|   if (dir === "right") {
189|     if (c === GRID_W - 1) return false;
190|     return !grid[r][c].right;
191|   }
192|   if (dir === "up") {
193|     if (r === 0) return false;
194|     return !grid[r - 1][c].bottom;
195|   }
196|   if (dir === "down") {
197|     if (r === GRID_H - 1) return false;
198|     return !grid[r][c].bottom;
199|   }
200|   return false;
201| }
202| 
203| function anyLegalMove() {
204|   if (stepsLeft <= 0) return false;
205|   const dirs = ["left", "right", "up", "down"];
206|   for (const d of dirs) {
207|     if (canMove(hedgehogRow, hedgehogCol, d)) return true;
208|   }
209|   return false;
210| }
211| 
212| function tryMove(dir) {
213|   if (state !== "playing" || paused) return;
214|   if (!canMove(hedgehogRow, hedgehogCol, dir)) return;
215|   if (dir === "left") hedgehogCol -= 1;
216|   if (dir === "right") hedgehogCol += 1;
217|   if (dir === "up") hedgehogRow -= 1;
218|   if (dir === "down") hedgehogRow += 1;
219|   lane = hedgehogCol;
220|   moves += 1;
221|   stepsLeft -= 1;
222| 
223|   const cell = grid[hedgehogRow][hedgehogCol];
224|   if (cell.apple) {
225|     cell.apple = false;
226|     score += 10;
227|     CARTRIDGE.send("score", { value: score });
228|   }
229| 
230|   if (hedgehogRow === exitRow && hedgehogCol === exitCol) {
231|     score += 25;
232|     CARTRIDGE.send("score", { value: score });
233|     state = "ended";
234|     endReason = "win";
235|     message = "Sortie atteinte !";
236|     CARTRIDGE.send("end", { reason: "win", value: score });
237|   } else if (!anyLegalMove()) {
238|     state = "ended";
239|     endReason = "stuck";
240|     message = "Plus de pas possibles.";
241|     CARTRIDGE.send("end", { reason: "stuck", value: score });
242|   }
243|   draw();
244| }
245| 
246| // ---- Input: swipe lanes ----
247| const SWIPE_FRACTION = 0.08;
248| let pressX = 0;
249| let pressY = 0;
250| 
251| canvas.addEventListener("pointerdown", (event) => {
252|   pressX = event.clientX;
253|   pressY = event.clientY;
254|   if (state === "title") {
255|     beginPlay();
256|   }
257| });
258| 
259| canvas.addEventListener("pointerup", (event) => {
260|   if (state !== "playing") return;
261|   const dx = event.clientX - pressX;
262|   const dy = event.clientY - pressY;
263|   const w = canvas.clientWidth;
264|   const h = canvas.clientHeight;
265|   if (Math.abs(dx) < w * SWIPE_FRACTION && Math.abs(dy) < h * SWIPE_FRACTION) return;
266|   if (Math.abs(dx) > Math.abs(dy)) {
267|     if (dx > 0) tryMove("right");
268|     else tryMove("left");
269|   } else {
270|     if (dy > 0) tryMove("down");
271|     else tryMove("up");
272|   }
273| });
274| 
275| window.addEventListener("keydown", (event) => {
276|   if (state === "title" && (event.key === "Enter" || event.key === " ")) {
277|     beginPlay();
278|     return;
279|   }
280|   if (state !== "playing") return;
281|   if (event.key === "ArrowLeft") tryMove("left");
282|   if (event.key === "ArrowRight") tryMove("right");
283|   if (event.key === "ArrowUp") tryMove("up");
284|   if (event.key === "ArrowDown") tryMove("down");
285| });
286| 
287| function beginPlay() {
288|   if (state === "playing") return;
289|   score = 0;
290|   moves = 0;
291|   level = 1;
292|   setupLevel(level);
293|   state = "playing";
294|   endReason = null;
295|   CARTRIDGE.send("start");
296|   CARTRIDGE.send("level", { index: level });
297|   CARTRIDGE.send("score", { value: score });
298|   draw();
299| }
300| 
301| function backToTitle() {
302|   state = "title";
303|   endReason = null;
304|   message = "";
305|   draw();
306| }
307| 
308| // ---- Drawing helpers (paper-cut style) ----
309| function roundedRectPath(x, y, w, h, r, seedKey) {
310|   const pts = [
311|     [x, y], [x + w, y], [x + w, y + h], [x, y + h]
312|   ];
313|   ctx.beginPath();
314|   const rr = Math.min(r, w / 2, h / 2);
315|   // approximate irregular rounded rect using jittered corners
316|   const j0 = getJitter(seedKey + "-0");
317|   const j1 = getJitter(seedKey + "-1");
318|   const j2 = getJitter(seedKey + "-2");
319|   const j3 = getJitter(seedKey + "-3");
320|   ctx.moveTo(x + rr + j0.dx, y + j0.dy);
321|   ctx.lineTo(x + w - rr + j1.dx, y + j1.dy);
322|   ctx.quadraticCurveTo(x + w + j1.dx, y + j1.dy, x + w + j1.dx, y + rr + j1.dy);
323|   ctx.lineTo(x + w + j2.dx, y + h - rr + j2.dy);
324|   ctx.quadraticCurveTo(x + w + j2.dx, y + h + j2.dy, x + w - rr + j2.dx, y + h + j2.dy);
325|   ctx.lineTo(x + rr + j3.dx, y + h + j3.dy);
326|   ctx.quadraticCurveTo(x + j3.dx, y + h + j3.dy, x + j3.dx, y + h - rr + j3.dy);
327|   ctx.lineTo(x + j0.dx, y + rr + j0.dy);
328|   ctx.quadraticCurveTo(x + j0.dx, y + j0.dy, x + rr + j0.dx, y + j0.dy);
329|   ctx.closePath();
330| }
331| 
332| function drawCard(x, y, w, h, fill, seedKey, shadow) {
333|   ctx.save();
334|   if (shadow !== false) {
335|     ctx.shadowColor = "rgba(61,64,91,0.35)";
336|     ctx.shadowBlur = 6;
337|     ctx.shadowOffsetY = 3;
338|   }
339|   ctx.fillStyle = fill;
340|   roundedRectPath(x, y, w, h, Math.min(w, h) * 0.15, seedKey);
341|   ctx.fill();
342|   ctx.restore();
343| }
344| 
345| function drawText(text, x, y, size, color, align) {
346|   ctx.fillStyle = color;
347|   ctx.font = "bold " + size + "px -apple-system, Segoe UI, Roboto, Arial, sans-serif";
348|   ctx.textAlign = align || "center";
349|   ctx.textBaseline = "middle";
350|   ctx.fillText(text, x, y);
351| }
352| 
353| function drawHedgehog(cx, cy, size) {
354|   ctx.save();
355|   ctx.shadowColor = "rgba(61,64,91,0.35)";
356|   ctx.shadowBlur = 5;
357|   ctx.shadowOffsetY = 2;
358|   // body
359|   ctx.fillStyle = COL_ACCENT;
360|   ctx.beginPath();
361|   ctx.ellipse(cx, cy, size * 0.5, size * 0.4, 0, 0, Math.PI * 2);
362|   ctx.fill();
363|   ctx.restore();
364|   // spikes
365|   ctx.fillStyle = COL_LAYER;
366|   for (let i = -3; i <= 3; i++) {
367|     const angle = (i / 8) * Math.PI - Math.PI / 2.2;
368|     const sx = cx - Math.cos(angle) * size * 0.35;
369|     const sy = cy - Math.sin(angle) * size * 0.35 - size * 0.1;
370|     ctx.beginPath();
371|     ctx.moveTo(sx, sy);
372|     ctx.lineTo(sx - 6, sy - 12);
373|     ctx.lineTo(sx + 6, sy - 3);
374|     ctx.closePath();
375|     ctx.fill();
376|   }
377|   // face
378|   ctx.fillStyle = "#f4ecd8";
379|   ctx.beginPath();
380|   ctx.ellipse(cx + size * 0.35, cy + size * 0.05, size * 0.18, size * 0.14, 0, 0, Math.PI * 2);
381|   ctx.fill();
382|   ctx.fillStyle = COL_ACCENT;
383|   ctx.beginPath();
384|   ctx.arc(cx + size * 0.45, cy + size * 0.05, size * 0.03, 0, Math.PI * 2);
385|   ctx.fill();
386| }
387| 
388| function drawApple(cx, cy, size) {
389|   ctx.save();
390|   ctx.shadowColor = "rgba(61,64,91,0.3)";
391|   ctx.shadowBlur = 4;
392|   ctx.shadowOffsetY = 2;
393|   ctx.fillStyle = "#c1443a";
394|   ctx.beginPath();
395|   ctx.arc(cx, cy, size * 0.3, 0, Math.PI * 2);
396|   ctx.fill();
397|   ctx.restore();
398|   ctx.strokeStyle = COL_HILITE;
399|   ctx.lineWidth = 2;
400|   ctx.beginPath();
401|   ctx.moveTo(cx, cy - size * 0.3);
402|   ctx.lineTo(cx + size * 0.08, cy - size * 0.42);
403|   ctx.stroke();
404| }
405| 
406| function drawExitFlag(cx, cy, size) {
407|   ctx.fillStyle = COL_HILITE;
408|   ctx.beginPath();
409|   ctx.moveTo(cx - size * 0.25, cy - size * 0.35);
410|   ctx.lineTo(cx - size * 0.25, cy + size * 0.35);
411|   ctx.lineTo(cx - size * 0.28, cy + size * 0.35);
412|   ctx.lineTo(cx - size * 0.28, cy - size * 0.35);
413|   ctx.closePath();
414|   ctx.fill();
415|   ctx.beginPath();
416|   ctx.moveTo(cx - size * 0.25, cy - size * 0.35);
417|   ctx.lineTo(cx + size * 0.2, cy - size * 0.2);
418|   ctx.lineTo(cx - size * 0.25, cy - size * 0.05);
419|   ctx.closePath();
420|   ctx.fill();
421| }
422| 
423| // ---- Main draw ----
424| function draw() {
425|   const w = canvas.width / dpr;
426|   const h = canvas.height / dpr;
427|   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
428|   ctx.clearRect(0, 0, w, h);
429|   ctx.fillStyle = COL_BG;
430|   ctx.fillRect(0, 0, w, h);
431| 
432|   if (state === "title") {
433|     drawTitleScreen(w, h);
434|     return;
435|   }
436| 
437|   // layout board
438|   const margin = Math.min(w, h) * 0.05;
439|   const topBar = h * 0.12;
440|   const boardTop = topBar + margin;
441|   const boardW = w - margin * 2;
442|   const boardH = h - boardTop - margin;
443|   const cellW = boardW / GRID_W;
444|   const cellH = boardH / GRID_H;
445|   const cellSize = Math.min(cellW, cellH);
446|   const gridPxW = cellSize * GRID_W;
447|   const gridPxH = cellSize * GRID_H;
448|   const ox = (w - gridPxW) / 2;
449|   const oy = boardTop + (boardH - gridPxH) / 2;
450| 
451|   // top bar card
452|   drawCard(margin * 0.5, margin * 0.3, w - margin, topBar * 0.8, COL_LAYER, "topbar", true);
453|   drawText("Score: " + score, margin * 1.2, margin * 0.3 + topBar * 0.4, Math.max(14, cellSize * 0.28), "#f4ecd8", "left");
454|   drawText("Pas: " + Math.max(0, stepsLeft), w - margin * 1.2, margin * 0.3 + topBar * 0.4, Math.max(14, cellSize * 0.28), "#f4ecd8", "right");
455| 
456|   // background board plate
457|   drawCard(ox - 6, oy - 6, gridPxW + 12, gridPxH + 12, "#ddd0b0", "boardplate", true);
458| 
459|   // draw cells (floor tiles)
460|   for (let r = 0; r < GRID_H; r++) {
461|     for (let c = 0; c < GRID_W; c++) {
462|       const x = ox + c * cellSize;
463|       const y = oy + r * cellSize;
464|       const key = "cell-" + r + "-" + c;
465|       const isPath = (r === hedgehogRow && c === hedgehogCol);
466|       drawCard(x + 2, y + 2, cellSize - 4, cellSize - 4, "#f4ecd8", key, false);
467|     }
468|   }
469| 
470|   // exit marker
471|   {
472|     const x = ox + exitCol * cellSize + cellSize / 2;
473|     const y = oy + exitRow * cellSize + cellSize / 2;
474|     drawExitFlag(x, y, cellSize);
475|   }
476| 
477|   // apples
478|   for (let r = 0; r < GRID_H; r++) {
479|     for (let c = 0; c < GRID_W; c++) {
480|       if (grid[r][c].apple) {
481|         const x = ox + c * cellSize + cellSize / 2;
482|         const y = oy + r * cellSize + cellSize / 2;
483|         drawApple(x, y, cellSize);
484|       }
485|     }
486|   }
487| 
488|   // walls
489|   ctx.strokeStyle = COL_ACCENT;
490|   ctx.lineWidth = 2;
491|   for (let r = 0; r < GRID_H; r++) {
492|     for (let c = 0; c < GRID_W; c++) {
493|       const x = ox + c * cellSize;
494|       const y = oy + r * cellSize;
495|       const cell = grid[r][c];
496|       const jkey1 = "wall-r-" + r + "-" + c;
497|       const j1 = getJitter(jkey1);
498|       const jkey2 = "wall-b-" + r + "-" + c;
499|       const j2 = getJitter(jkey2);
500|       if (cell.right) {
501|         ctx.beginPath();
502|         ctx.moveTo(x + cellSize + j1.dx, y + j1.dy);
503|         ctx.lineTo(x + cellSize + j1.dx, y + cellSize + j1.dy);
504|         ctx.stroke();
505|       }
506|       if (cell.bottom) {
507|         ctx.beginPath();
508|         ctx.moveTo(x + j2.dx, y + cellSize + j2.dy);
509|         ctx.lineTo(x + cellSize + j2.dx, y + cellSize + j2.dy);
510|         ctx.stroke();
511|       }
512|     }
513|   }
514|   // outer border
515|   ctx.strokeRect(ox, oy, gridPxW, gridPxH);
516| 
517|   // hedgehog
518|   {
519|     const x = ox + hedgehogCol * cellSize + cellSize / 2;
520|     const y = oy + hedgehogRow * cellSize + cellSize / 2;
521|     drawHedgehog(x, y, cellSize * 0.7);
522|   }
523| 
524|   if (state === "ended") {
525|     drawEndOverlay(w, h);
526|   }
527| 
528|   if (paused) {
529|     drawPauseOverlay(w, h);
530|   }
531| }
532| 
533| function drawTitleScreen(w, h) {
534|   const cardW = Math.min(w * 0.85, 520);
535|   const cardH = h * 0.4;
536|   const cx = w / 2;
537|   const cy = h * 0.35;
538|   drawCard(cx - cardW / 2, cy - cardH / 2, cardW, cardH, COL_LAYER, "titlecard", true);
539|   drawText("Le Labyrinthe", cx, cy - cardH * 0.18, Math.max(20, cardW * 0.09), "#f4ecd8", "center");
540|   drawText("du Hérisson", cx, cy + cardH * 0.05, Math.max(20, cardW * 0.09), "#f4ecd8", "center");
541| 
542|   drawHedgehog(cx, cy + cardH * 0.35, cardW * 0.14);
543| 
544|   const btnW = cardW * 0.7;
545|   const btnH = h * 0.09;
546|   const bx = cx - btnW / 2;
547|   const by = h * 0.72;
548|   drawCard(bx, by, btnW, btnH, COL_HILITE, "startbtn", true);
549|   drawText("Glissez ou touchez pour jouer", cx, by + btnH / 2, Math.max(14, btnH * 0.32), COL_ACCENT, "center");
550| 
551|   drawText("Guidez le hérisson vers la sortie", cx, h * 0.88, Math.max(12, h * 0.025), COL_ACCENT, "center");
552| }
553| 
554| function drawEndOverlay(w, h) {
555|   ctx.save();
556|   ctx.fillStyle = "rgba(61,64,91,0.55)";
557|   ctx.fillRect(0, 0, w, h);
558|   ctx.restore();
559| 
560|   const cardW = Math.min(w * 0.8, 480);
561|   const cardH = h * 0.3;
562|   const cx = w / 2;
563|   const cy = h / 2;
564|   drawCard(cx - cardW / 2, cy - cardH / 2, cardW, cardH, COL_LAYER, "endcard", true);
565|   const title = endReason === "win" ? "Bravo !" : "Coincé !";
566|   drawText(title, cx, cy - cardH * 0.2, Math.max(20, cardH * 0.22), "#f4ecd8", "center");
567|   drawText(message, cx, cy + cardH * 0.05, Math.max(14, cardH * 0.13), "#f4ecd8", "center");
568|   drawText("Score final: " + score, cx, cy + cardH * 0.28, Math.max(14, cardH * 0.13), "#f4ecd8", "center");
569| 
570|   const btnW = cardW * 0.6;
571|   const btnH = cardH * 0.28;
572|   const bx = cx - btnW / 2;
573|   const by = cy + cardH * 0.42;
574|   drawCard(bx, by, btnW, btnH, COL_HILITE, "replaybtn", true);
575|   drawText("Toucher pour rejouer", cx, by + btnH / 2, Math.max(12, btnH * 0.35), COL_ACCENT, "center");
576| }
577| 
578| function drawPauseOverlay(w, h) {
579|   ctx.save();
580|   ctx.fillStyle = "rgba(244,236,216,0.7)";
581|   ctx.fillRect(0, 0, w, h);
582|   ctx.restore();
583|   drawText("Pause", w / 2, h / 2, Math.max(20, h * 0.05), COL_ACCENT, "center");
584| }
585| 
586| // tap to replay after end
587| canvas.addEventListener("pointerup", (event) => {
588|   if (state === "ended") {
589|     state = "title";
590|     endReason = null;
591|     message = "";
592|     draw();
593|   }
594| });
595| 
596| // ---- Boot ----
597| resize();
598| draw();
599| CARTRIDGE.send("boot", { title: "Le Labyrinthe du Hérisson", gameType: "puzzle-board", lang: "fr" });
600| </script>
601| </body>
602| </html>
603|

